                    How do you prefer to receive notifications?
                    <span class="required-indicator" aria-hidden="true">*</span>
                  </legend>
                  <p id="notification-help" class="field-help">
                    Choose one option. You can update this preference later.
                  </p>
                  <div class="option-list">
                    ${options.map((option) => RadioOption(option)).join("")}
                  </div>
                </fieldset>
              </div>

              <div class="actions">
                <button class="submit-button" type="submit">Save preference</button>
                <p
                  id="form-status"
                  class="status-message"
                  aria-live="polite"
                  data-state="idle"
                ></p>
              </div>
            </form>
          </div>
        </section>
      `;

